<script setup lang="ts">
import { ref,onMounted,computed } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { Plus,ArrowLeft,ArrowUpRight,Printer,Check,Trash2,FileText,Sparkles,ClipboardPlus } from 'lucide-vue-next'
import { api,post,today,statusName,kindName } from '../api'
import MathText from '../components/MathText.vue'
import Modal from '../components/Modal.vue'
import EmptyState from '../components/EmptyState.vue'
const route=useRoute(),router=useRouter(),papers=ref<any[]>([]),paper=ref<any>(null),questions=ref<any[]>([]),students=ref<any[]>([]),error=ref(''),busy=ref(false),show=ref(false),generating=ref(false),student=ref(''),testDate=ref(today()),search=ref(''),selected=ref(''),maximum=ref(5)
const form=ref({title:'',count:5,tags:'',kind:'',difficulty:''})
const available=computed(()=>questions.value.filter(q=>q.status==='approved'&&(q.stem+q.tags.join('')).includes(search.value)))
async function load(){try{if(route.params.id)paper.value=await api(`papers/${route.params.id}/`);else papers.value=await api('papers/')}catch(e:any){error.value=e.message}}
onMounted(async()=>{await load();try{[questions.value,students.value]=await Promise.all([api('questions/'),api('students/')])}catch(e:any){error.value=e.message}})
async function run(fn:()=>Promise<any>){busy.value=true;error.value='';try{return await fn()}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function create(){await run(async()=>{const data=await post(generating.value?'papers/generate/':'papers/',generating.value?{...form.value,count:Number(form.value.count),difficulty:form.value.difficulty?Number(form.value.difficulty):undefined,tags:form.value.tags.split(/[、,，]/).filter(Boolean)}:{title:form.value.title});show.value=false;await router.push('/papers/'+data.id)})}
async function add(){await run(async()=>{await post(`papers/${paper.value.id}/items/`,{question:selected.value,max_score:maximum.value});selected.value='';await load()})}
async function publish(){await run(async()=>{await post(`papers/${paper.value.id}/publish/`);await load()})}
async function remove(item:string){await run(async()=>{await post(`papers/${paper.value.id}/remove-item/`,{item});await load()})}
async function submission(){await run(async()=>{const result=await post('submissions/',{student:student.value,paper:paper.value.id,test_date:testDate.value});await router.push('/grading/'+result.id)})}
function questionFor(item:any){return item.snapshot.stem?item.snapshot:questions.value.find(q=>q.id===item.question)||{}}
</script>
<template><div class="page-heading"><div><RouterLink v-if="paper" to="/papers" class="back-link"><ArrowLeft :size="15"/>试卷与练习</RouterLink><p v-else class="eyebrow">PAPERS & PRACTICE</p><h1>{{paper?paper.title:'每一份练习，都有针对性'}}<span class="heading-dot">.</span></h1><p class="subtitle">{{paper?'发布后固定题目与答案版本，历史记录始终可回溯。':'从私有题库组卷，也可以直接录入外部试卷。'}}</p></div><div class="inline wrap"><template v-if="!paper"><button class="button secondary" @click="show=true;generating=true"><Sparkles :size="17"/>按条件组卷</button><button class="button primary" @click="show=true;generating=false"><Plus :size="17"/>手动组卷</button></template><template v-else><RouterLink v-if="paper.status==='published'" :to="'/print/'+paper.id" class="button secondary"><Printer :size="17"/>打印 / 导出 PDF</RouterLink><button v-else class="button primary" :disabled="busy||!paper.items.length" @click="publish"><Check :size="17"/>发布试卷</button></template></div></div><div v-if="error" class="notice danger">{{error}}</div>
 <template v-if="!paper"><section class="panel"><div v-if="papers.length" class="table-scroll"><table><thead><tr><th>试卷名称</th><th>来源</th><th>题量</th><th>状态</th><th></th></tr></thead><tbody><tr v-for="p in papers" @click="router.push('/papers/'+p.id)"><td><div class="file-cell"><span class="file-icon"><FileText :size="20"/></span><strong>{{p.title}}</strong></div></td><td>{{({generated:'系统组卷',external:'外部试卷',practice:'错题复练'} as any)[p.source]}}</td><td>{{p.items.length}} 道</td><td><span class="status" :class="p.status">{{statusName[p.status]}}</span></td><td><ArrowUpRight :size="17"/></td></tr></tbody></table></div><EmptyState v-else title="组一份有针对性的练习" text="先审核题库中的题目与答案，再选择题目生成试卷。"/></section></template>
 <template v-else><section class="panel paper-summary"><div class="inline wrap"><span class="status" :class="paper.status">{{statusName[paper.status]}}</span><span>{{paper.items.length}} 道题</span><span v-if="!paper.is_fragment">满分 {{paper.items.reduce((sum:number,item:any)=>sum+Number(item.max_score),0)}} 分</span><span v-else class="tag amber">零散题目 · 不计整卷总分</span></div><div v-if="paper.status==='published'" class="form-grid submission-form"><label>关联学生<select v-model="student"><option value="">请选择学生</option><option v-for="s in students" :value="s.id">{{s.name}}</option></select></label><label>测试日期<input v-model="testDate" type="date"/></label><div class="inline wrap span-2"><a v-if="student" :href="`/api/papers/${paper.id}/card/?student=${student}`" class="button secondary"><Printer :size="16"/>下载专属答题卡 PDF</a><button class="button primary" :disabled="!student||busy" @click="submission"><ClipboardPlus :size="16"/>建立作答记录</button><RouterLink :to="`/imports?new=1`" class="text-button">上传学生纸笔作答<ArrowUpRight :size="15"/></RouterLink></div></div></section>
 <section v-if="paper.status==='draft'" class="panel padded"><h2>添加已审核题目</h2><div class="form-grid"><label>筛选题干 / 知识点<input v-model="search" placeholder="搜索可用题目"/></label><label>本题分值<input v-model="maximum" type="number" min="0.01" max="1000" step="0.01"/></label><label class="span-2">选择题目<select v-model="selected"><option value="">请选择已审核题目</option><option v-for="q in available" :value="q.id">{{kindName[q.kind]}} · {{q.stem.slice(0,100)}}</option></select></label></div><button class="button primary" :disabled="!selected||busy" @click="add"><Plus :size="17"/>加入试卷</button></section>
 <article v-for="item in paper.items" :key="item.id" class="question-card"><header class="question-top"><div class="inline"><span class="question-number">{{item.label}}</span><span class="tag">{{kindName[questionFor(item).kind]}}</span><span class="muted small">{{item.max_score}} 分</span></div><button v-if="paper.status==='draft'" class="icon-button" aria-label="移除题目" @click="remove(item.id)"><Trash2 :size="17"/></button></header><MathText :text="questionFor(item).stem"/><div class="options-grid"><MathText v-for="option in questionFor(item).options" :text="option"/></div><details v-if="item.snapshot.answer"><summary>参考答案与解析（已固定版本）</summary><MathText :text="item.snapshot.answer+'\n'+item.snapshot.explanation"/></details></article><EmptyState v-if="!paper.items.length" title="试卷还是空白的" text="添加已审核题目，或回到题库继续收集。"/></template>
 <Modal v-if="show" :title="generating?'按条件生成候选卷':'新建试卷'" @close="show=false"><form @submit.prevent="create"><div v-if="error" class="notice danger">{{error}}</div><label>试卷名称<input v-model="form.title" required maxlength="200"/></label><template v-if="generating"><div class="form-grid"><label>题目数量<input v-model="form.count" type="number" min="1" max="100" required/></label><label>题型<select v-model="form.kind"><option value="">不限</option><option v-for="(name,key) in kindName" :value="key">{{name}}</option></select></label><label>难度<select v-model="form.difficulty"><option value="">不限</option><option v-for="n in 5" :value="n">{{n}}</option></select></label><label>知识点（任一命中）<input v-model="form.tags" placeholder="顿号分隔"/></label></div><p class="helper">只使用已审核题目；题量不足时会提示调整条件。</p></template><button class="button primary full" :disabled="busy">{{busy?'处理中…':generating?'生成候选卷':'建立试卷'}}</button></form></Modal>
</template>
